SELECT o.id AS order_id, c.name AS customer_name, o.amount
FROM orders o
JOIN customers c ON o.customer_id = c.id
ORDER BY o.id ASC;
`;

sql-basic-select-filter.promptSeed:
Write a PostgreSQL query to filter, sort, and paginate product inventory:

## Description

### Application Context
In a retail database (`inventory/products`), you need to retrieve in-stock electronics for a featured catalog section.

```ts
interface ProductRecord {
  id: number;
  name: string;
  category: string;
  price: number;
  stock: number;
}

interface ProductFilterResult {
  id: number;
  name: string;
  price: number;
  stock: number;
}
```

### Table Schema

- **`products`**:
  - `id`: `INT` (Primary Key)
  - `name`: `VARCHAR(50)`
  - `category`: `VARCHAR(50)`
  - `price`: `INT`
  - `stock`: `INT`

### Requirements

Write a SQL query string assigned to `const query`:
- **Projection**: Select `id`, `name`, `price`, and `stock` from `products`.
- **Filter**: Include only products where `category = 'Electronics'` and `stock > 0`.
- **Sort**: Order results by `price ASC` (cheapest first). For items with identical price, break ties by `name ASC` alphabetically.
- **Pagination**: Limit the output to the first `3` records.

sql-basic-select-filter.testHarness:
await (async () => {
  const userSql = typeof query === 'function' ? query() : (typeof query !== 'undefined' ? query : '');
  async function runSafe(db, sql) {
    try {
      return (await db.query(sql)).rows;
    } catch {
      return null;
    }
  }

  const db = new PGlite();
  await db.exec(`
    CREATE TABLE products (
      id INT PRIMARY KEY,
      name VARCHAR(50),
      category VARCHAR(50),
      price INT,
      stock INT
    );
  `);

  // Case 1: Filters by category and stock, sorts by price ASC then name ASC, and limits to 3
  await db.exec(`
    DELETE FROM products;
    INSERT INTO products VALUES
      (1, 'Laptop', 'Electronics', 999, 10),
      (2, 'Keyboard', 'Electronics', 50, 25),
      (3, 'Mouse', 'Electronics', 50, 15),
      (4, 'Desk Lamp', 'Home', 40, 5),
      (5, 'Headphones', 'Electronics', 120, 0),
      (6, 'Webcam', 'Electronics', 75, 8);
  `);
  const r1 = await runSafe(db, userSql);
  $test.check(
    'Filters by category and stock, sorts by price ASC then name ASC, and limits to 3',
    r1 !== null && $test.equal(r1, [
      { id: 2, name: 'Keyboard', price: 50, stock: 25 },
      { id: 3, name: 'Mouse', price: 50, stock: 15 },
      { id: 6, name: 'Webcam', price: 75, stock: 8 }
    ]),
    r1
  );

  // Case 2: Excludes out-of-stock electronics even if price is lowest
  await db.exec(`
    DELETE FROM products;
    INSERT INTO products VALUES
      (1, 'USB Cable', 'Electronics', 10, 0),
      (2, 'Flash Drive', 'Electronics', 15, 4);
  `);
  const r2 = await runSafe(db, userSql);
  $test.check(
    'Excludes out-of-stock electronics even if price is lowest',
    r2 !== null && $test.equal(r2, [
      { id: 2, name: 'Flash Drive', price: 15, stock: 4 }
    ]),
    r2
  );

  // Case 3: Returns empty array when no matching in-stock electronics exist
  await db.exec(`
    DELETE FROM products;
    INSERT INTO products VALUES
      (1, 'Sofa', 'Home', 500, 2),
      (2, 'Chair', 'Home', 150, 5);
  `);
  const r3 = await runSafe(db, userSql);
  $test.check(
    'Returns empty array when no matching in-stock electronics exist',
    r3 !== null && $test.equal(r3, []),
    r3
  );

  // Case 4: Returns empty array on completely empty products table
  await db.exec(`DELETE FROM products;`);
  const r4 = await runSafe(db, userSql);
  $test.check(
    'Returns empty array on completely empty products table',
    r4 !== null && $test.equal(r4, []),
    r4
  );
})();

sql-basic-aggregate-group.testHarness:
await (async () => {
  const userSql = typeof query === 'function' ? query() : (typeof query !== 'undefined' ? query : '');
  async function runSafe(db: any, sql: string) {
    try {
      const res = await db.query(sql);
      return res.rows.map((row: any) => ({
        ...row,
        employee_count: Number(row.employee_count),
        avg_salary: Number(row.avg_salary),
      }));
    } catch {
      return null;
    }
  }

  const db = new PGlite();
  await db.exec(`
    CREATE TABLE employees (
      id INT PRIMARY KEY,
      name VARCHAR(50),
      department VARCHAR(50),
      salary INT
    );
  `);

  const case1 = 'Groups by department with count >= 2, calculates avg_salary, and sorts by employee_count DESC then department ASC';
  const case2 = 'Excludes single-employee departments via HAVING filter';
  const case3 = 'Rounds average salary accurately to 2 decimal places';
  const case4 = 'Returns empty array when no department has at least 2 employees';

  // Case 1: Standard aggregation and multi-key sorting
  await db.exec(`
    DELETE FROM employees;
    INSERT INTO employees VALUES
      (1, 'Alice', 'Engineering', 120000),
      (2, 'Bob', 'Engineering', 100000),
      (3, 'Charlie', 'Engineering', 110000),
      (4, 'Diana', 'Marketing', 80000),
      (5, 'Evan', 'Marketing', 70000),
      (6, 'Fiona', 'Design', 95000);
  `);
  const r1 = await runSafe(db, userSql);
  $test.check(
    case1,
    r1 !== null && $test.equal(r1, [
      { department: 'Engineering', employee_count: 3, avg_salary: 110000 },
      { department: 'Marketing', employee_count: 2, avg_salary: 75000 },
    ]),
    r1
  );

  // Case 2: Excludes departments with only 1 employee
  await db.exec(`
    DELETE FROM employees;
    INSERT INTO employees VALUES
      (1, 'George', 'Finance', 90000),
      (2, 'Hannah', 'HR', 75000),
      (3, 'Ian', 'Support', 60000),
      (4, 'Julia', 'Support', 64000);
  `);
  const r2 = await runSafe(db, userSql);
  $test.check(
    case2,
    r2 !== null && $test.equal(r2, [
      { department: 'Support', employee_count: 2, avg_salary: 62000 },
    ]),
    r2
  );

  // Case 3: Rounds average salary to 2 decimal places
  await db.exec(`
    DELETE FROM employees;
    INSERT INTO employees VALUES
      (1, 'Kevin', 'Research', 100000),
      (2, 'Laura', 'Research', 105000),
      (3, 'Mike', 'Research', 102500);
  `);
  const r3 = await runSafe(db, userSql);
  $test.check(
    case3,
    r3 !== null && r3.length === 1 && r3[0].department === 'Research' && r3[0].employee_count === 3 && r3[0].avg_salary === 102500,
    r3
  );

  // Case 4: Returns empty array when no department has at least 2 employees
  await db.exec(`
    DELETE FROM employees;
    INSERT INTO employees VALUES
      (1, 'Nina', 'Legal', 130000),
      (2, 'Oscar', 'Security', 115000);
  `);
  const r4 = await runSafe(db, userSql);
  $test.check(
    case4,
    r4 !== null && Array.isArray(r4) && r4.length === 0,
    r4
  );
})();
